import assert from 'assert';
import {readiness,blockingReason,canEnableDebugger,setupChecks} from './readiness.js';
const catalog={debugger_code:'configured',server_version:'17',database:'test',current_user:'owner',routines:[{oid:1,debug_allowed:true}],selected:{oid:1,arguments:[{name:'a',type:'integer',mode:'IN',supported:true}]}};
assert.equal(blockingReason(catalog),'');
assert.equal(readiness(catalog).filter(r=>r.state==='ready').length,6);
assert.match(blockingReason({...catalog,debugger_code:'missing_extension'}),/CREATE EXTENSION/);
assert.equal(readiness({...catalog,debugger_code:'missing_extension'}).find(r=>r.label.includes('plugin_debugger')).state,'warning');
assert.equal(blockingReason({...catalog,debugger_code:'unverified'}),'');
assert.match(blockingReason({...catalog,debugger_code:'plugin_not_configured'}),/перезапустить/);
assert.match(blockingReason({...catalog,routines:[{oid:1,debug_allowed:false}]}),/Войдите как владелец/);
assert.match(blockingReason({...catalog,selected:{oid:1,arguments:[{name:'id',type:'uuid',mode:'IN',supported:false}]}}),/uuid/);
const defaultOnly={...catalog,selected:{oid:1,arguments:[{name:'host',type:'inet',mode:'IN',supported:false,has_default:true}]}};
assert.equal(blockingReason(defaultOnly),'');
assert.equal(readiness(defaultOnly).find(row=>row.label==='Входные аргументы').state,'warning');
assert.equal(readiness(null).length,0);
const absent={extension_created:false,package_available:true,superuser:true,read_only:false,preload:true,api_allowed:false};
const withSetup=changes=>({...catalog,debugger_setup:{...absent,...changes}});
assert.equal(canEnableDebugger(withSetup({})),true);
assert.equal(canEnableDebugger(withSetup({extension_created:true})),false);
assert.equal(canEnableDebugger(withSetup({superuser:false})),false);
assert.equal(canEnableDebugger(withSetup({read_only:true})),false);
assert.equal(canEnableDebugger(withSetup({package_available:false})),false);
assert.match(setupChecks(withSetup({package_available:false})).extension[1],/Установите пакет/);
assert.match(setupChecks(withSetup({read_only:true})).extension[1],/только для чтения/);
assert.match(setupChecks(withSetup({superuser:false})).extension[1],/суперпользователь/);
assert.match(setupChecks(withSetup({preload:false,restart_pending:true})).preload[1],/ожидает перезапуска/);
assert.equal(setupChecks(withSetup({preload:null})).preload[0],'warning');
assert.match(setupChecks(withSetup({extension_created:true})).access[1],/USAGE/);
const foreignObject={...withSetup({extension_created:true,api_allowed:true}),routines:[{oid:1,debug_allowed:false,owner:'other_owner'}]};
assert.match(blockingReason(foreignObject),/other_owner/);
assert.ok(readiness(foreignObject,{includeObject:false}).every(check=>check.state==='ready'));
assert.ok(readiness(withSetup({}),{includeObject:false}).some(check=>check.state==='blocked'));
console.log('Readiness: configured, unavailable extension, hidden plugin state, preload, owner and input types passed.');
